// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotNull;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.concurrent.atomic.AtomicLong;

import org.junit.jupiter.api.Test;

class LmdbNativeSafetyLedgerTest {

	private static final LmdbNativeProbeConfig CONFIG = LmdbNativeProbeConfig.defaults();

	@Test
	void creditStartsAtZeroAndAccruesTheEtaFraction() {
		AtomicLong clock = new AtomicLong();
		LmdbNativeSafetyLedger ledger = new LmdbNativeSafetyLedger(CONFIG, clock::get);
		assertEquals(0L, ledger.availableNanos(), "the ledger starts at zero — stale credit never survives restart");
		assertNull(ledger.tryReserve(1L), "no credit, no probe");
		ledger.earn(1_000_000_000L);
		// alpha 0.05 -> eta = 0.05/0.95
		assertEquals((long) (1_000_000_000L * 0.05 / 0.95), ledger.availableNanos(), 2L);
	}

	@Test
	void reservationsNeverExceedCreditAndRefundOrCommitExactlyOnce() {
		AtomicLong clock = new AtomicLong();
		LmdbNativeSafetyLedger ledger = new LmdbNativeSafetyLedger(CONFIG, clock::get);
		ledger.earn(19_000_000_000L); // credit = 1e9
		long credit = ledger.availableNanos();

		LmdbNativeSafetyLedger.Reservation first = ledger.tryReserve(credit / 2);
		assertNotNull(first);
		assertNull(ledger.tryReserve(credit), "outstanding reservations count against credit");
		LmdbNativeSafetyLedger.Reservation second = ledger.tryReserve(credit / 2);
		assertNotNull(second);
		assertNull(ledger.tryReserve(1L), "fully reserved");

		first.refund();
		assertEquals(credit / 2, ledger.availableNanos(), 2L, "a refund releases without charging");
		first.refund();
		assertEquals(credit / 2, ledger.availableNanos(), 2L, "refund is idempotent");

		second.commit(credit); // overshoot: actual charge exceeds the reservation
		assertEquals(0L, ledger.availableNanos(), "overshoot debits the actual cost, never clamped");
		second.commit(credit);
		assertEquals(0L, ledger.availableNanos(), "commit is idempotent");
	}

	@Test
	void anUnsettledReservationRefundsOnClose() {
		AtomicLong clock = new AtomicLong();
		LmdbNativeSafetyLedger ledger = new LmdbNativeSafetyLedger(CONFIG, clock::get);
		ledger.earn(19_000_000_000L);
		long before = ledger.availableNanos();
		try (LmdbNativeSafetyLedger.Reservation reservation = ledger.tryReserve(before)) {
			assertEquals(0L, ledger.availableNanos());
		}
		assertEquals(before, ledger.availableNanos(), "close is the refund safety net");
	}

	@Test
	void spacingRequiresBothDecisionsAndElapsedTime() {
		AtomicLong clock = new AtomicLong();
		LmdbNativeSafetyLedger ledger = new LmdbNativeSafetyLedger(CONFIG, clock::get);
		assertTrue(ledger.spacingAllows(), "a fresh ledger does not block the first probe on spacing");

		ledger.noteProbeDecision();
		assertFalse(ledger.spacingAllows(), "no two probes run consecutively");

		for (int i = 0; i < CONFIG.minSpacingDecisions(); i++) {
			assertFalse(ledger.spacingAllows(), "both spacing conditions must hold");
			ledger.noteNormalDecision();
		}
		assertFalse(ledger.spacingAllows(), "decisions alone are not enough — time must also pass");
		clock.addAndGet(CONFIG.minSpacingNanos());
		assertTrue(ledger.spacingAllows(), "decisions plus elapsed time reopen probing");
	}
}
